function Drawer({ title, children, onClose, dirty = false }: { title: string; children: ReactNode; onClose: () => void; dirty?: boolean }) {
  const drawerRef = useRef<HTMLElement>(null)
  const returnFocusRef = useRef<HTMLElement | null>(document.activeElement instanceof HTMLElement ? document.activeElement : null)
  useEffect(() => {
    const drawer = drawerRef.current
    const focusable = drawer?.querySelectorAll<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')
    const first = focusable?.[0]
    first?.focus()
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { if (!dirty || window.confirm('Хадгалаагүй өөрчлөлт байна. Хаах уу?')) onClose(); return }
      if (event.key !== 'Tab' || !focusable?.length) return
      const current = document.activeElement
      const firstFocusable = focusable[0]
      const lastFocusable = focusable[focusable.length - 1]
      if (event.shiftKey && current === firstFocusable) { event.preventDefault(); lastFocusable.focus() }
      else if (!event.shiftKey && current === lastFocusable) { event.preventDefault(); firstFocusable.focus() }
    }
    document.addEventListener('keydown', onKey)
    return () => { document.removeEventListener('keydown', onKey); returnFocusRef.current?.focus() }
  }, [dirty, onClose])
  const close = () => { if (!dirty || window.confirm('Хадгалаагүй өөрчлөлт байна. Хаах уу?')) onClose() }
  return createPortal(
    <div className="payroll-setup-scrim" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && close()}><aside ref={drawerRef} className="payroll-setup-drawer" role="dialog" aria-modal="true" aria-label={title}><header><div><span className="payroll-v2-kicker">ТОХИРГОО</span><h2>{title}</h2></div><button className="payroll-setup-icon-button" onClick={close} aria-label="Хаах"><X size={18} /></button></header><div className="payroll-setup-drawer-body">{children}</div></aside></div>,
    document.body,
  )
}

function FormActions({ pending, onCancel, submitLabel = 'Хадгалах' }: { pending?: boolean; onCancel: () => void; submitLabel?: string }) {
  return <footer className="payroll-setup-form-actions"><button type="button" className="payroll-v2-button secondary" onClick={onCancel}>Цуцлах</button><button className="payroll-v2-button primary" type="submit" disabled={pending}>{pending ? 'Хадгалж байна…' : <><Save size={14} />{submitLabel}</>}</button></footer>
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="payroll-setup-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>
}

function SectionHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="payroll-setup-section-header"><div><span className="payroll-v2-kicker">{eyebrow}</span><h2>{title}</h2><p>{description}</p></div>{action}</div>
}

